"""Prepare complete synthetic reference/prepared-bias background and native deviation examples."""
import json
from pathlib import Path
from prepare_chromvar_background_request import ROOT,BASE,save
from validate_mashr_native import pin
DEST=ROOT/'examples/chromvar-background'
def main():
    assert not DEST.exists();DEST.mkdir();inputs=DEST/'inputs';inputs.mkdir();data=json.loads((BASE/'background-original-controls-1/cases.json').read_bytes());counts=data['datasets']['baseline']['counts'];peaks=['peak'+str(i+1) for i in range(20)];cells=['cell'+str(i+1) for i in range(6)];triples=[(i+1,j+1,v) for i,r in enumerate(counts) for j,v in enumerate(r) if v]
    (inputs/'counts.mtx').write_text('%%MatrixMarket matrix coordinate real general\n20 6 '+str(len(triples))+'\n'+''.join(f'{i} {j} {v}\n' for i,j,v in triples),encoding='utf8',newline='\n')
    for name,values in [('peaks.tsv',peaks),('cells.tsv',cells)]:(inputs/name).write_text(''.join(v+'\n' for v in values),encoding='utf8',newline='\n')
    sequence='';ranges=[];bias=[]
    for i,peak in enumerate(peaks):
        gc=6+(i*13)%23;seq='GC'*(gc//2)+('G' if gc%2 else '')+'A'*(40-gc)+'NNNNN';start=len(sequence)+1;sequence+=seq;ranges.append(f'{peak}\tchr1\t{start}\t{len(sequence)}\n');bias.append(f'{peak}\t{gc/40}\n')
    (inputs/'reference.fa').write_text('>chr1\n'+'\n'.join(sequence[i:i+80] for i in range(0,len(sequence),80))+'\n',encoding='ascii',newline='\n');(inputs/'reference.fa.fai').write_text('chr1\t900\t6\t80\t81\n',encoding='ascii',newline='\n');(inputs/'ranges.tsv').write_text('peak_id\tchromosome\tstart\tend\n'+''.join(ranges),encoding='utf8',newline='\n');(inputs/'bias.tsv').write_text('peak_id\tbias\n'+''.join(bias),encoding='utf8',newline='\n');(inputs/'motif-labels.tsv').write_text('motif_id\tmotif_name\nmotif-multi\tMulti\nmotif-single\tSingle\nmotif-empty\tEmpty\n',encoding='utf8',newline='\n');(inputs/'motif-members.tsv').write_text('motif_id\tpeak_id\n'+''.join('motif-multi\t'+peaks[i-1]+'\n' for i in [1,3,5,7,11])+'motif-single\tpeak2\n',encoding='utf8',newline='\n')
    background=dict(schema_version=1,mode='BACKGROUND',profile='1.34.1-package',out='../../build/chromvar-background-demo-NEW',genome_build='synthetic-not-a-reference-genome',bias_provenance='synthetic canonical-base GC; ambiguity excluded; not a biological result',counts='inputs/counts.mtx',peak_features='inputs/peaks.tsv',cells='inputs/cells.tsv',fasta='inputs/reference.fa',fai='inputs/reference.fa.fai',peak_ranges='inputs/ranges.tsv',seed=17,niterations=7,w=.1,bs=10,timeout=90,rscript='C:/Program Files/R/R-4.6.1/bin/Rscript.exe',r_motif_library='../../build/literature-review/signac-runtime/motif-reference-setup-1/R-lib',r_signac_library='../../build/literature-review/signac-runtime/reference-setup-1/R-lib',r_base_library='../../build/omics-sctransform-r');save(DEST/'request.json',background)
    legacy=dict(background);legacy.update(profile='1.16.0-source',out='../../build/chromvar-background-legacy-demo-NEW',bias='inputs/bias.tsv');[legacy.pop(k) for k in ['fasta','fai','peak_ranges']];save(DEST/'legacy-request.json',legacy)
    deviations=dict(schema_version=1,mode='DEVIATIONS',profile='1.34.1-package',out='../../build/chromvar-background-deviations-demo-NEW',genome_build=background['genome_build'],motif_collection='synthetic-source-controls-not-JASPAR',background_provenance='original chromVAR source/public replay; synthetic example; seed17 iterations7 w0.1 bs10; inspect background capture warnings and manifests',counts='inputs/counts.mtx',peak_features='inputs/peaks.tsv',cells='inputs/cells.tsv',motif_labels='inputs/motif-labels.tsv',annotation_peaks='inputs/motif-members.tsv',background='../../build/chromvar-background-demo-NEW/background.tsv');save(DEST/'deviations-request.json',deviations)
    legacy_deviations=dict(deviations);legacy_deviations.update(profile='1.16.0-source',out='../../build/chromvar-background-legacy-deviations-demo-NEW',background='../../build/chromvar-background-legacy-demo-NEW/background.tsv');save(DEST/'legacy-deviations-request.json',legacy_deviations)
    for name,analysis in [('verify-request','chromvar-background-demo-NEW'),('legacy-verify-request','chromvar-background-legacy-demo-NEW'),('deviations-verify-request','chromvar-background-deviations-demo-NEW'),('legacy-deviations-verify-request','chromvar-background-legacy-deviations-demo-NEW')]:save(DEST/(name+'.json'),dict(schema_version=1,mode='VERIFY',analysis='../../build/'+analysis))
    (DEST/'.gitattributes').write_text('*.json -text\ninputs/* -text\n',encoding='utf8',newline='\n');out=BASE/'background-example-preparation-1';out.mkdir();save(out/'COMPLETED.json',dict(status='prepared-complete-synthetic-background-and-native-deviation-examples',source=pin(Path(__file__)),files={p.relative_to(DEST).as_posix():pin(p) for p in DEST.rglob('*') if p.is_file()},biological_result=False));print('Prepared current reference and legacy explicit-bias examples with native score follow-ups')
if __name__=='__main__':main()
